import re

class SensitiveData(BaseModel):
    ssn: str
    credit_card: str

    @field_validator('ssn')
    @classmethod
    def validate_ssn(cls, v):
        if not re.match(r'^\d{3}-\d{2}-\d{4}$', v):
            raise ValueError('Invalid SSN format')
        return v

    @field_validator('credit_card')
    @classmethod
    def mask_credit_card(cls, v):
        cleaned = re.sub(r'[^\d]', '', v)
        if len(cleaned) != 16:
            raise ValueError('Invalid credit card')
        return f"****-****-****-{cleaned[-4:]}"

    class Config:
        json_schema_extra = {
            "example": {
                "ssn": "123-45-6789",
                "credit_card": "****-****-****-1234"
            }
        }

